# Find connected components for color 3 (horizontal segments only)
def find_segments(cells, dim):
    # dim=0 means horizontal segments (same row, consecutive columns)
    # dim=1 means vertical segments (same column, consecutive rows)
    if not cells:
        return []
    if dim == 0:  # Horizontal segments (group by row)
        groups = {}
        for r, c in cells:
            if r not in groups:
                groups[r] = [c]
            else:
                groups[r].append(c)
        segments = []
        for r, cols in groups.items():
            cols.sort()
            segs = [cols[0]]
            for i in range(1, len(cols)):
                if cols[i] == cols[i-1] + 1:
                    segs.append(cols[i])
                else:
                    sections = [segs]
                    segs = [cols[i]]
                    sections.append(segs)
            segments.extend(sections)
        return segments
    else:
        # Vertical (group by column, not implemented here)
        raise NotImplementedError

# Count horizontal segments for each color
def count_segments(cells):
    groups = {}
    for r, c in cells:
        if r not in groups:
            groups[r] = []
        groups[r].append(c)

    segments = []
    for r, cols in sorted(groups.items()):
        cols.sort()
        if cols:
            seg_start = cols[0]
            seg_end = cols[0]
            for c in cols[1:]:
                if c == seg_end + 1:
                    seg_end = c
                else:
                    segments.append((seg_end - seg_start + 1))
                    seg_start = seg_end = c
            segments.append((seg_end - seg_start + 1))
    return segments

